import 'dart:convert';
import 'dart:io';

void main() {
  final json = buildQuestionBank();
  final file = File('../assets/data/jlpt_questions.json');
  final encoder = JsonEncoder.withIndent('  ');
  file.writeAsStringSync(encoder.convert(json));
  // ignore: avoid_print
  print('Generated jlpt_questions.json with ${countQuestions(json)} questions!');
}

int countQuestions(Map json) {
  int count = 0;
  for (final level in (json['levels'] as Map).values) {
    for (final qs in (level as Map).values) {
      count += (qs as List).length;
    }
  }
  return count;
}

