        'grammar': _n4Grammar(),
        'kanji': _n4Kanji(),
        'reading': _n4Reading(),
      },
      'N3': {
        'vocabulary': _n3Vocab(),
        'grammar': _n3Grammar(),
        'kanji': _n3Kanji(),
        'reading': _n3Reading(),
      },
      'N2': {
        'vocabulary': _n2Vocab(),
        'grammar': _n2Grammar(),
        'kanji': _n2Kanji(),
        'reading': _n2Reading(),
      },
      'N1': {
        'vocabulary': _n1Vocab(),
        'grammar': _n1Grammar(),
        'kanji': _n1Kanji(),
        'reading': _n1Reading(),
      },
    },
  };
}

Q q(String id, String question, List<String> options, int correctIndex, String difficulty, String explanation) {
  return Q(id: id, question: question, options: options, correctIndex: correctIndex, difficulty: difficulty, explanation: explanation);
}

class Q {
  final String id, question, difficulty, explanation;
  final List<String> options;
  final int correctIndex;
  Q({required this.id, required this.question, required this.options, required this.correctIndex, required this.difficulty, required this.explanation});
  Map<String, dynamic> toJson() => {
    'id': id, 'question': question, 'options': options, 'correctIndex': correctIndex, 'difficulty': difficulty, 'explanation': explanation,
  };
}

